use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

fn transient(msg: &str) -> RetryError {
    RetryError::Transient(msg.to_string())
}

fn permanent(msg: &str) -> RetryError {
    RetryError::Permanent(msg.to_string())
}

#[test]
fn succeeds_after_transient_failures() {
    let cfg = config(5, 100, 1000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(transient("blip"))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![100, 200, 400]);
}

#[test]
fn permanent_error_is_not_retried() {
    let cfg = config(5, 100, 1000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        Err(permanent("missing job"))
    });
    assert_eq!(result, Err(permanent("missing job")));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn attempts_are_bounded_and_include_first_call() {
    let cfg = config(3, 25, 1000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        Err(transient("blip"))
    });
    assert_eq!(result, Err(transient("blip")));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![25, 50]);
}

#[test]
fn delays_saturate_at_max_delay_ms() {
    let cfg = config(100, 1, 1000);
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&cfg, &mut sleeper, || Err(transient("blip")));
    assert!(result.is_err());
    // 99 retries: delays 2^0..=2^9 grow to 512, the rest saturate at 1000.
    let mut expected = (0..10).map(|i| 1u64 << i).collect::<Vec<_>>();
    expected.extend(std::iter::repeat(1000).take(89));
    assert_eq!(sleeper.sleeps, expected);
}

